import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { EmptyState, Pill } from "../../components/UI";

const IlanKart = ({ ilan, onClick }) => (
  <div className="card" style={{ marginBottom: 10, borderLeft: "3px solid var(--sari)", cursor: "pointer", borderRadius: "var(--r-lg)" }} onClick={onClick}
    onMouseEnter={e => e.currentTarget.style.borderLeftColor = "var(--turuncu)"}
    onMouseLeave={e => e.currentTarget.style.borderLeftColor = "var(--sari)"}
  >
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 10 }}>
      <div className="display" style={{ fontSize: 18 }}>{ilan.yuk}</div>
      <div className="price">₺{ilan.ucret.toLocaleString()}</div>
    </div>
    <div className="rota" style={{ marginBottom: 10 }}>
      <span className="rota-city">{ilan.nereden}</span>
      <span className="rota-arrow">—→</span>
      <span className="rota-city">{ilan.nereye}</span>
    </div>
    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
      <Pill durum={ilan.ton > 0 ? "aktif" : "issiz"} />
      <span className="chip chip-blue">⏱ {ilan.sure}</span>
      <span className="chip">📅 {ilan.tarih}</span>
      <span className="chip">🚛 {ilan.aracTip}</span>
    </div>
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: 10, borderTop: "1px solid var(--border)" }}>
      <span style={{ fontSize: 13, fontWeight: 500, color: "var(--text2)" }}>🏢 {ilan.olusturan}</span>
      <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
        <span className="rating">⭐ {ilan.olusturanPuan}</span>
        <span className="chip" style={{ fontSize: 10 }}>{ilan.istekSayisi} istek</span>
      </div>
    </div>
  </div>
);

export default function IlanlarSayfasi() {
  const { ilanlar, ilanAl, oturum } = useApp();
  const [filtre, setFiltre] = useState("");
  const [secilen, setSecilen] = useState(null);

  const liste = ilanlar.filter(i =>
    i.nereden.toLowerCase().includes(filtre.toLowerCase()) ||
    i.nereye.toLowerCase().includes(filtre.toLowerCase()) ||
    i.yuk.toLowerCase().includes(filtre.toLowerCase())
  );

  const sec = () => {
    if (!oturum) return;
    ilanAl(secilen.id, oturum);
    setSecilen(null);
  };

  return (
    <div className="scroll-content">
      <div className="search-bar" style={{ marginBottom: 12 }}>
        <span className="search-icon">🔍</span>
        <input placeholder="Şehir veya yük türü ara..." value={filtre} onChange={e => setFiltre(e.target.value)} />
        {filtre && <button onClick={() => setFiltre("")} style={{ color: "var(--text3)", fontSize: 14 }}>✕</button>}
      </div>

      <div className="section-title">AKTİF İLANLAR ({liste.length})</div>

      {liste.length === 0
        ? <EmptyState icon="🔍" text="Sonuç bulunamadı" />
        : liste.map(i => <IlanKart key={i.id} ilan={i} onClick={() => setSecilen(i)} />)
      }

      {secilen && (
        <div className="sheet-overlay" onClick={() => setSecilen(null)}>
          <div className="sheet">
            <button onClick={() => setSecilen(null)} style={{ position: "fixed", top: 20, right: 20, background: "var(--bg1)", border: "1px solid var(--border)", borderRadius: "var(--r)", padding: "12px", fontSize: 16, cursor: "pointer", zIndex: 101 }}>✕</button>
            <div style={{ maxWidth: 440, margin: "0 auto", padding: 24, paddingTop: 60 }}>
              <div className="display" style={{ fontSize: 24, color: "var(--sari)", marginBottom: 4 }}>{secilen.yuk}</div>
              <div className="rota" style={{ marginBottom: 6 }}>
                <span className="rota-city">{secilen.nereden}</span>
                <span className="rota-arrow">—→</span>
                <span className="rota-city">{secilen.nereye}</span>
              </div>
              <div style={{ color: "var(--text2)", fontSize: 13, lineHeight: 1.7, marginBottom: 16 }}>{secilen.aciklama}</div>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 16 }}>
                {[
                  { k: "Tonaj", v: secilen.ton > 0 ? `${secilen.ton} Ton` : "Serbest" },
                  { k: "Ücret", v: `₺${secilen.ucret.toLocaleString()}` },
                  { k: "Süre", v: secilen.sure },
                  { k: "Araç Tipi", v: secilen.aracTip },
                  { k: "Tarih", v: secilen.tarih },
                  { k: "Ödeme Planı", v: secilen.odemeGun === 0 ? "Peşin" : `${secilen.odemeGun} Gün` },
                ].map(({ k, v }) => (
                  <div key={k} style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "10px 12px" }}>
                    <div className="label" style={{ marginBottom: 3 }}>{k}</div>
                    <div style={{ fontSize: 13, fontWeight: 600 }}>{v}</div>
                  </div>
                ))}
              </div>

              <button onClick={sec} className="btn btn-primary btn-display btn-full" style={{ fontSize: 18, padding: "16px", marginTop: 20 }}>
                🚚 İLANI SEÇ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
